begin;create extension if not exists pgtap with schema extensions;select plan(24);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values
('00000000-0000-0000-0000-000000000000','99900000-0000-4000-8000-000000000040','authenticated','authenticated','analytics-owner@example.test','',now(),now(),now()),
('00000000-0000-0000-0000-000000000000','99900000-0000-4000-8000-000000000041','authenticated','authenticated','analytics-limited@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000040',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000040","role":"authenticated"}',true);
select public.create_business('analytics-test','Analytics Test Inc','Analytics Test','sole_proprietorship','retail','{"city":"Manila"}');
select set_config('test.analytics_org',(select id::text from public.organizations where slug='analytics-test'),true);
select set_config('test.analytics_main',(select id::text from public.branches where organization_id=current_setting('test.analytics_org')::uuid and code='main'),true);
select set_config('test.analytics_version',(select version.id::text from public.business_os_template_versions version join public.business_os_templates template on template.id=version.template_id where template.key='retail-store-os'and version.status='published'order by version.version desc limit 1),true);
select public.install_business_os_template(current_setting('test.analytics_org')::uuid,current_setting('test.analytics_version')::uuid);
select public.set_business_module_state(current_setting('test.analytics_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.analytics_org')::uuid,'inventory',true,'{"allow_negative_stock":false}');select public.set_business_module_state(current_setting('test.analytics_org')::uuid,'sales',true,'{}');select public.set_business_module_state(current_setting('test.analytics_org')::uuid,'pos',true,'{}');
reset role;insert into public.branches(organization_id,code,name,address)values(current_setting('test.analytics_org')::uuid,'north','North Branch','{}')returning id;select set_config('test.analytics_north',(select id::text from public.branches where organization_id=current_setting('test.analytics_org')::uuid and code='north'),true);
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000040',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000040","role":"authenticated"}',true);
select set_config('test.analytics_main_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.analytics_org')::uuid and branch_id=current_setting('test.analytics_main')::uuid),true);select set_config('test.analytics_north_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.analytics_org')::uuid and branch_id=current_setting('test.analytics_north')::uuid),true);
select set_config('test.analytics_product',public.save_catalog_product(current_setting('test.analytics_org')::uuid,null,null,'product','Analytics Widget','',null,null,'piece',100,60,'exclusive',0,'active',false,'[{"name":"Default","sku":"AN-001","attributes":{},"status":"active"}]','[]')::text,true);
select set_config('test.analytics_variant',(select id::text from public.product_variants where product_id=current_setting('test.analytics_product')::uuid),true);select set_config('test.analytics_item',public.configure_inventory_item(current_setting('test.analytics_org')::uuid,null,current_setting('test.analytics_variant')::uuid,5,8,true)::text,true);
select public.record_stock_movement(current_setting('test.analytics_org')::uuid,current_setting('test.analytics_item')::uuid,current_setting('test.analytics_main_location')::uuid,'opening_balance',10,60,'Main opening','analytics-main-opening');select public.record_stock_movement(current_setting('test.analytics_org')::uuid,current_setting('test.analytics_item')::uuid,current_setting('test.analytics_north_location')::uuid,'opening_balance',20,60,'North opening','analytics-north-opening');
select set_config('test.analytics_customer',public.save_sales_customer(current_setting('test.analytics_org')::uuid,null,'Analytics Customer','09171234567','analytics@example.test')::text,true);
select public.save_pos_transaction(current_setting('test.analytics_org')::uuid,null,current_setting('test.analytics_main')::uuid,current_setting('test.analytics_main_location')::uuid,current_setting('test.analytics_customer')::uuid,'completed','99900000-0000-4000-8000-000000000401',now(),('[{"productVariantId":"'||current_setting('test.analytics_variant')||'","quantity":2,"discountAmount":0}]')::jsonb,'[{"method":"cash","amount":200,"reference":""}]');
select public.save_pos_transaction(current_setting('test.analytics_org')::uuid,null,current_setting('test.analytics_north')::uuid,current_setting('test.analytics_north_location')::uuid,null,'completed','99900000-0000-4000-8000-000000000402',now(),('[{"productVariantId":"'||current_setting('test.analytics_variant')||'","quantity":3,"discountAmount":0}]')::jsonb,'[{"method":"cash","amount":300,"reference":""}]');
select results_eq($$select count(*)from public.analytics_metric_definitions where is_enabled$$,$$select 14::bigint$$,'Registry contains exactly the allowlisted metrics');
select ok((select bool_and(char_length(description)>30)from public.analytics_metric_definitions),'Every metric has a clear definition');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'sales_today')->>'value')::numeric,500::numeric,'Sales today aggregates all accessible branches');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'sales_today',null,null,current_setting('test.analytics_main')::uuid)->>'value')::numeric,200::numeric,'Explicit Branch filtering isolates sales');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'average_transaction_value')->>'value')::numeric,250::numeric,'Average transaction value uses qualifying transaction count');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'gross_margin')->>'value')::numeric,40::numeric,'Gross margin uses recorded line cost and net line sales');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'inventory_value')->>'value')::numeric,1500::numeric,'Inventory value uses current quantities and average costs');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'inventory_value',null,null,current_setting('test.analytics_main')::uuid)->>'value')::numeric,480::numeric,'Inventory value respects Branch access');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'low_stock_count')->>'value')::int,0,'Low stock uses configured thresholds');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'customer_count')->>'value')::int,1,'Customer count applies the selected date period');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'repeat_customer_rate')->>'value')::numeric,0::numeric,'Repeat rate has a defined zero denominator outcome');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'top_products')#>>'{value,0,unitsSold}')::numeric,5::numeric,'Top products rank net units from accessible sales');
select is(jsonb_array_length(public.query_business_metric(current_setting('test.analytics_org')::uuid,'slow_moving_products')->'value'),0,'A sold stocked product is not slow moving');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'sales_today',((now()at time zone'Asia/Manila')::date-1),((now()at time zone'Asia/Manila')::date-1))->>'value')::numeric,0::numeric,'Date filters use Philippine-local inclusive dates');
select is(public.query_business_metric(current_setting('test.analytics_org')::uuid,'sales_growth')->'value','null'::jsonb,'Growth is null when the comparison period has no sales');
select throws_ok($$select public.query_business_metric(current_setting('test.analytics_org')::uuid,'inventory_value',current_date-1,current_date)$$,'22023','This metric is a current snapshot and does not accept date filters.','Snapshot metrics reject misleading dates');
select throws_ok($$select public.query_business_metric(current_setting('test.analytics_org')::uuid,'raw_table_query')$$,'22023','Unknown or unavailable metric.','Arbitrary metric and raw-query names are rejected');
select throws_ok($$select public.query_business_metric(current_setting('test.analytics_org')::uuid,'top_products',null,null,null,26)$$,'22023','Metric result limit must be between 1 and 25.','List result limits are bounded');
reset role;insert into public.organization_memberships(organization_id,user_id,status,joined_at,branch_access_mode)values(current_setting('test.analytics_org')::uuid,'99900000-0000-4000-8000-000000000041','active',now(),'selected')returning id;insert into public.membership_roles(membership_id,role_id)select membership.id,role.id from public.organization_memberships membership join public.roles role on role.organization_id=membership.organization_id and role.key='owner'where membership.organization_id=current_setting('test.analytics_org')::uuid and membership.user_id='99900000-0000-4000-8000-000000000041';insert into public.membership_branch_access(organization_id,membership_id,branch_id)select current_setting('test.analytics_org')::uuid,membership.id,current_setting('test.analytics_main')::uuid from public.organization_memberships membership where membership.organization_id=current_setting('test.analytics_org')::uuid and membership.user_id='99900000-0000-4000-8000-000000000041';
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000041',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000041","role":"authenticated"}',true);
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'sales_today')->>'value')::numeric,200::numeric,'All-Branch query includes only Branches assigned to the caller');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'inventory_value')->>'value')::numeric,480::numeric,'Snapshot aggregation also restricts selected Branch access');
select is((public.query_business_metric(current_setting('test.analytics_org')::uuid,'top_products')#>>'{value,0,unitsSold}')::numeric,2::numeric,'Ranked metrics exclude inaccessible Branch sales');
select throws_ok($$select public.query_business_metric(current_setting('test.analytics_org')::uuid,'sales_today',null,null,current_setting('test.analytics_north')::uuid)$$,'42501','Permission denied.','Explicit access to an unassigned Branch is denied');
select throws_ok($$select public.query_business_metric('00000000-0000-4000-8000-000000000999','sales_today')$$,'42501','Permission denied.','Cross-tenant metric access is denied');
select results_eq($$select value_type,default_period,supports_date_filter from public.analytics_metric_definitions where key='inventory_value'$$,$$select 'currency'::text,'current_snapshot'::text,false$$,'Registry publishes date behavior and result type');
select *from finish();rollback;
